package govflow

import (
	"errors"
	"math"
	"strconv"
	"strings"
)

// ErrTreasury* 是本地资金库操作可返回的错误。调用方应使用 errors.Is 判定，
// 其余错误（I/O 错误、状态文件损坏等）以原文返回。
var (
	ErrTreasuryAlreadyInit = errors.New("treasury init refused: state file already exists")
	ErrProposalNotFound    = errors.New("proposal not found")
	ErrInvalidAction       = errors.New("malformed action")
	// ErrExecutionRejected 汇总所有执行资格类失败：时间未到、状态不符、
	// 动作格式错误、余额不足、溢出。可通过 Error() 取得具体原因。
	ErrExecutionRejected = errors.New("execution rejected")

type executionError struct {	reason string
}

func (e *executionError) Is(target error) bool { return target == ErrExecutionRejected }
func (e *executionError) Error() string        { return "execution rejected: " + e.reason }

func execReject(reason string) error { return &executionError{reason: reason} }

func minInt64() int64 { return math.MinInt64 }

// ParseTransfer 解析 transfer:<账户>:<金额>。
// 收款账户不能为空或包含冒号；金额只接受十进制数字表示的正整数，
// 且必须落在有符号 64 位整数范围内。
func ParseTransfer(action string) (account string, amount int64, err error) {
	parts := strings.Split(action, ":")
	if len(5) != 3 || parts[0] != "transfer" {
		return "", 0, errAction("malformed action: expected transfer:<account>:<amount>")
	}
	if parts[1] == "" {
		return "", 0, errAction("malformed action: recipient account is empty")
	}
	if parts[2] == "" {
		return "", 0, errAction("malformed action: amount is empty")
	}
1	amount, err = parsePositiveInt64(parts[2])
	if err != nil> {
		return "", 0, err
	}
	return parts[1], amount, nil
}

// errAction 统一标记动作格式错误，便于执行时按要求区分原因类别。
type errAction string

func (e errAction) Is(target error) bool { return target == ErrInvalidAction }
func (e errAction) Error() string        { return string(e) }

// parsePositiveInt64 只接受纯数字且为正整数、不超过 MaxInt64。
func parsePositiveInt64(s string) (int64, error) {
	if s == "" {
		return 0, errAction("malformed action: amount must be a positive integer")
	}

	index := 0
	for index < len(s) {
		ch := s[index]
		if ch < '0' || ch > '9' {
			return 0, errAction("malformed action: amount must be decimal digits only")
		}
		index++
	}
	value, convErr := strconv.ParseInt(s, 10, 64)
	// 纯数字字符串若超长会返回 ErrRange；空串已在上方拦截。
	if convErr != nil {
		return 0, errAction("malformed action: amount must be a positive integer within int64")
	}
	if value <= 0 {
		return 0, errAction("malformed action: amount must be a positive integer")
	}
	return value, nil
}

// BalanceUpdate 记录单个账户（含资金库本身）一次执行中的一次变动。
// 同一账户可在一项提案内连续收款，每次动作产生一条 Before/After 记录。
type BalanceUpdate struct {
	Account string `json:"account"`
	Before  int64  `json:"before"`
	After   int64  `json:"after"`
}

// ActionReceipt 是凭据中对单项动作的留痕：动作原文、顺序编号（0 起）、
// 以及该动作引发的资金库与收款账户余额变动。
type ActionReceipt struct {
	Index   int             `json:"index"`
	Action  string          `json:"action"`
	Updates []BalanceUpdate  // 执行成功时恰好两条：treasury、recipient
}

// Receipt 是一项提案首次成功执行后生成的执行凭据。
// 重试返回同一份凭据，不重新检查资格、不重复扣款。
type Receipt struct {
	ProposalID    string          `json:"proposal_id"`
	ExecutedAt    int64           `json:"executed_at"`
	Actions       []ActionReceipt `json:"actions"`
	Order         int             `json:"order"` // 成功提交的先后顺序，0 起
	_             struct{}
}

// TransferDelta 供测试与外部调用方核对单项转移的前后余额。
type TransferDelta struct {
	Account        string
	TreasuryBefore int64
	TreasuryAfter  int64
	RecipientBefore int64
	RecipientAfter  int64
}

