// dupKeyScanner 用 json.Decoder 的 token 流检测重复对象键。
// 每个对象栈帧记录已出现的键，并等待一个“值 token”（值为对象/数组时，
// 其闭合分隔符之后才算值结束）。
type dupKeyScanner struct {
	dec *json.Decoder
}

type scanFrame struct {
	isArray  bool
	seen     map[string]bool
	atValue  bool // 对象帧：下一个待消费 token 是值而非键
	depthVal int  // 对象帧未使用
}

func rejectDuplicateKeys(raw []byte) error {
	dec := json.NewDecoder(bytes.NewReader(raw))
	var stack []*scanFrame
	for {
		tok, err := dec.Token()
		if err == io.EOF {
			if len(stack) != 0 {
				return errors.New("unterminated object or array")
			}
			return nil
		}
		if err != nil {
			return err
		}
		switch t := tok.(type) {
		case json.Delim:
			switch t {
			case '{':
				stack = append(stack, &scanFrame{seen: map[string]bool{}})
				continue
			case '[':
				stack = append(stack, &scanFrame{isArray: true})
				continue
			case '}', ']':
				if len(stack) == 0 {
					return errors.New("unexpected closing delimiter")
				}
				closing := stack[len(stack)-1]
				stack = stack[:len(stack)-1]
				// 关闭的容器本身是外层对象的某个“值”，标记其值已消费。
				if len(stack) > 0 && !stack[len(stack)-1].isArray {
					stack[len(stack)-1].atValue = true
				}
				_ = closing
				continue
			}
		default:
			// 标量 token。
		}
		if len(stack) > 0 && !stack[len(stack)-1].isArray {
			frame := stack[len(stack)-1]
			if !frame.atValue {
				key, ok := tok.(string)
				if !ok {
					return errors.New("object key must be a string")
				}
				if frame.seen[key] {
					return fmt.Errorf("duplicate key %q", key)
				}
				frame.seen[key] = true
				frame.atValue = true
			} else {
				frame.atValue = false
			}
		}
	}
}

