func rejectUnknownAndDupKeys(raw []byte) error {
	dec := json.NewDecoder(bytes.NewReader(raw))
	type frame struct {
		isArray bool
		seen    map[string]int // 对象键 -> 已出现次数
	}
	stack := []frame{}
	for {
		tok, err := dec.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			return err
		}
		switch t := tok.(type) {
		case json.Delim:
			switch t {
			case '{':
				stack = append(stack, frame{seen: map[string]int{}})
			case '[':
				stack = append(stack, frame{isArray: true})
			case '}', ']':
				if len(stack) == 0 {
					return errors.New("unexpected closing delimiter")
				}
				stack = stack[:len(stack)-1]
			}
		case string:
			// 字符串 token 只可能是对象键（值为字符串时下一 token 成对出现，
			// 但 Token API 不区分二者）：借助栈顶对象 + More 判断不可靠，
