		_ = lockFD.Close()
		if errors.Is(err, fs.ErrExist) {
			return nil, fmt.Errorf("%w: %s", ErrTreasuryAlreadyInit, path)
		}
		return nil, err
	}
	_ = fd.Close()

	store := &Store{path: path, lockFD: lockFD}
	if err := store.commitLocked(newStoredState(treasury)); err != nil {
		_ = store.funlock()
		_ = lockFD.Close()
		_ = os.Remove(path)
		return nil, err
