17	// 资金库状态文件相关错误。
18	var (
19		// ErrTreasuryAlreadyInit：初始化目标路径已存在文件，新文件才能初始化。
20		ErrTreasuryAlreadyInit = errors.New("treasury init refused: state file already exists")
21		// ErrStateCorrupt：状态文件损坏或不是受支持的资金库状态文件。
22		ErrStateCorrupt = errors.New("treasury state file is corrupt")
23		// ErrProposalNotFound：按编号查询或执行时提案不存在。
24		ErrProposalNotFound = errors.New("proposal not found")
25		// ErrProposalConflict：同编号提案再次登记但时间锁或动作原文与首次不同。
26		ErrProposalConflict = errors.New("proposal already registered with different timelock or actions")
27		// ErrInvalidRegistration：登记参数非法（编号为空、初始余额越界等）。
28		ErrInvalidRegistration = errors.New("invalid registration")
29	)
30	
31	const (
32		stateMagic   = "govflow-treasury-state"
33		stateVersion = 1
34		lockSuffix   = ".lock"
35	)
36	
37	// BalanceUpdate 记录一个账户在一次动作前后的余额。
38	type BalanceUpdate struct {
39		Account string `json:"account"`
40		Before  int64  `json:"before"`
41		After   int64  `json:"after"`
42	}
43	
44	// ActionReceipt 是凭据中对单项动作的留痕：动作原文、在提案中的顺序编号（0 起），
45	// 以及该动作引发的资金库与收款账户余额变动。
46	type ActionReceipt struct {
47		Index     int           `json:"index"`
48		Action    string        `json:"action"`
49		Treasury  BalanceUpdate `json:"treasury"`
50		Recipient BalanceUpdate `json:"recipient"`
51	}
52	
53	// Receipt 是一项提案首次成功执行后生成的执行凭据。
54	// 一项提案只允许成功一次；重试返回同一份凭据。
55	type Receipt struct {
56		ProposalID string          `json:"proposal_id"`
57		ExecutedAt int64           `json:"executed_at"` // 首次成功执行时调用方提供的时间
58		Order      int             `json:"order"`       // 成功提交的先后顺序，0 起
59		Actions    []ActionReceipt `json:"actions"`
60	}
61	
62	// ProposalRecord 是已登记提案的对外视图。State 只可能是 passed 或 executed。
63	type ProposalRecord struct {
64		ID          string
65		State       string
66		TimelockEnd int64
67		Actions     []string
68	}
69	
70	// ---- 磁盘结构（JSON） ----
71	
72	type storedProposal struct {
73		ID          string   `json:"id"`
74		State       string   `json:"state"`
75		TimelockEnd int64    `json:"timelock_end"`
76		Actions     []string `json:"actions"`
77	}
78	
79	type storedState struct {
80		Magic           string                     `json:"magic"`
81		Version         int                        `json:"version"`
82		InitialTreasury int64                      `json:"initial_treasury"`
83		Treasury        int64                      `json:"treasury"`
84		Balances        map[string]int64           `json:"balances"`
85		Proposals       map[string]*storedProposal `json:"proposals"`
86		Receipts        []*Receipt                 `json:"receipts"`
87	}
88	
89	// Store 是绑定到单个本地状态文件的资金库句柄。
90	// 多个 goroutine 可并发使用同一个 Store；不同 Store/进程操作同一状态文件时，
91	// 通过进程内互斥锁与文件锁（flock）串行化。
92	type Store struct {
93		path   string
94		mu     sync.Mutex // 保护本句柄上的全部操作
95		lockFD *os.File   // 跨进程文件锁
96		closed bool
97	}
98	
99	// 进程内按规范路径共享的互斥锁，保证同进程内多个 Store 句柄也互相串行。
100	var (
101		pathLocksMu sync.Mutex
102		pathLocks   = map[string]*sync.Mutex{}
103	)
104	
105	func keyFor(path string) string {
106		if resolved, err := filepath.EvalSymlinks(path); err == nil {
107			path = resolved
108		}
109		if abs, err := filepath.Abs(path); err == nil {
110			path = abs
111		}
112		return path
113	}
114	
115	func inProcessLock(path string) *sync.Mutex {
116		key := keyFor(path)
117		pathLocksMu.Lock()
118		defer pathLocksMu.Unlock()
119		m, ok := pathLocks[key]
120		if !ok {
121			m = &sync.Mutex{}
122			pathLocks[key] = m
123		}
124		return m
125	}
126	
127	// InitTreasury 创建一个全新的状态文件并写入初始资金库余额。
128	// 只有新文件才能初始化：路径已存在（含损坏文件）一律拒绝，不会重置或覆盖。
129	// treasury 必须落在有符号 64 位整数范围内且不得为负。
130	func InitTreasury(path string, treasury int64) (*Store, error) {
131		if treasury < 0 {
132			return nil, fmt.Errorf("%w: initial treasury balance must not be negative", ErrInvalidRegistration)
133		}
134		pathMu := inProcessLock(path)
135		pathMu.Lock()
136		defer pathMu.Unlock()
137	
138		// 先打开/创建锁文件并取跨进程锁，再创建状态文件，消除“空文件已出现、
139		// 尚未写入”期间被其它进程 Open 判为损坏的窗口。
140		lockFD, err := os.OpenFile(path+lockSuffix, os.O_RDWR|os.O_CREATE, 0o600)
141		if err != nil {
142			return nil, err
143		}
144		if err := syscall.Flock(int(lockFD.Fd()), syscall.LOCK_EX); err != nil {
145			_ = lockFD.Close()
146			return nil, err
147		}
148		// O_EXCL 保证与并发初始化竞争时只有一方成功。
149		fd, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
150		if err != nil {
151			_ = syscall.Flock(int(lockFD.Fd()), syscall.LOCK_UN)
152			_ = lockFD.Close()
153			if errors.Is(err, fs.ErrExist) {
154				return nil, fmt.Errorf("%w: %s", ErrTreasuryAlreadyInit, path)
155			}
156			return nil, err
157		}
158		_ = fd.Close()
159	
160		store := &Store{path: path, lockFD: lockFD}
161		if err := store.commitLocked(newStoredState(treasury)); err != nil {
162			_ = store.funlock()
163			_ = lockFD.Close()
164			_ = os.Remove(path)
165			return nil, err
166		}
167		// 初始化完成后立即释放跨进程锁；后续每次操作各自短持锁。
168		if err := store.funlock(); err != nil {
169			_ = lockFD.Close()
170			_ = os.Remove(path)
171			return nil, err
172		}
173		return store, nil
174	}
175	
176	// Open 打开已有的资金库状态文件。文件损坏时明确拒绝，不会重建或覆盖原文件。
177	func Open(path string) (*Store, error) {
178		pathMu := inProcessLock(path)
179		pathMu.Lock()
180		defer pathMu.Unlock()
181		return openStoreHoldingPathLock(path)
182	}
183	
184	// openStoreHoldingPathLock 的调用方必须持有该路径的进程内互斥锁。
185	func openStoreHoldingPathLock(path string) (*Store, error) {
186		if _, err := os.Stat(path); err != nil {
187			return nil, err
188		}
189		lockFD, err := os.OpenFile(path+lockSuffix, os.O_RDWR|os.O_CREATE, 0o600)
190		if err != nil {
191			return nil, err
192		}
193		if err := syscall.Flock(int(lockFD.Fd()), syscall.LOCK_EX); err != nil {
194			_ = lockFD.Close()
195			return nil, err
196		}
197		store := &Store{path: path, lockFD: lockFD}
198		if _, err := store.loadLocked(); err != nil {
199			_ = store.funlock()
200			_ = lockFD.Close()
201			return nil, err
202		}
203		// 打开时已做严格校验；锁随即释放，每次操作再各自短持锁。
204		if err := store.funlock(); err != nil {
205			_ = lockFD.Close()
206			return nil, err
207		}
208		return store, nil
209	}
210	
211	// Path 返回状态文件路径。
212	func (s *Store) Path() string { return s.path }
213	
214	// Close 释放文件锁。关闭后其它操作返回错误。
215	func (s *Store) Close() error {
216		s.mu.Lock()
217		defer s.mu.Unlock()
218		if s.closed {
219			return nil
220		}
221		s.closed = true
222		if err := s.funlock(); err != nil {
223			_ = s.lockFD.Close()
224			return err
225		}
226		return s.lockFD.Close()
227	}
228	
229	func (s *Store) flock(how int) error {
230		if s.lockFD == nil {
231			return errors.New("treasury store is closed")
232		}
233		return syscall.Flock(int(s.lockFD.Fd()), how)
234	}
235	
236	func (s *Store) funlock() error {
237		if s.lockFD == nil {
238			return nil
239		}
240		return syscall.Flock(int(s.lockFD.Fd()), syscall.LOCK_UN)
241	}
242	
243	// begin 串行化一次读改写操作：先取进程内路径锁，再取跨进程排他文件锁。
244	// 返回的 commit 在操作结束时释放锁。
245	func (s *Store) begin() (func(), error) {
246		pathMu := inProcessLock(s.path)
247		pathMu.Lock()
248		s.mu.Lock()
249		if s.closed {
250			s.mu.Unlock()
251			pathMu.Unlock()
252			return nil, errors.New("treasury store is closed")
253		}
254		if err := s.flock(syscall.LOCK_EX); err != nil {
255			s.mu.Unlock()
256			pathMu.Unlock()
257			return nil, err
258		}
259		return func() {
260			_ = s.funlock()
261			s.mu.Unlock()
262			pathMu.Unlock()
263		}, nil
264	}
265	
266	func newStoredState(treasury int64) *storedState {
267		return &storedState{
268			Magic:           stateMagic,
269			Version:         stateVersion,
270			InitialTreasury: treasury,
271			Treasury:        treasury,
272			Balances:        map[string]int64{},
273			Proposals:       map[string]*storedProposal{},
274			Receipts:        []*Receipt{},
275		}
276	}
277	
278	// ---- 登记 ----
279	
280	// Register 登记一项已通过（passed）的提案，保留时间锁与动作原文。
281	// 编号必须非空；动作列表可为空（执行时会因动作为空被拒绝），动作原文不做改写。
282	// 同编号且时间锁、动作原文与首次登记完全相同的重试返回 existed=true；
283	// 内容不同则返回 ErrProposalConflict。
284	func (s *Store) Register(id string, timelockEnd int64, actions []string) (existed bool, err error) {
285		if id == "" {
286			return false, fmt.Errorf("%w: proposal id must not be empty", ErrInvalidRegistration)
287		}
288		commit, err := s.begin()
289		if err != nil {
290			return false, err
291		}
292		defer commit()
293	
294		state, err := s.loadLocked()
295		if err != nil {
296			return false, err
297		}
298		stored := copyActions(actions)
299		if existing, ok := state.Proposals[id]; ok {
300			if existing.TimelockEnd == timelockEnd && sameActions(existing.Actions, stored) {
301				return true, nil
302			}
303			return false, fmt.Errorf("%w: proposal %s", ErrProposalConflict, id)
304		}
305		state.Proposals[id] = &storedProposal{
306			ID:          id,
307			State:       "passed",
308			TimelockEnd: timelockEnd,
309			Actions:     stored,
310		}
311		if err := s.commitLocked(state); err != nil {
312			return false, err
313		}
314		return false, nil
315	}
316	
317	func copyActions(actions []string) []string {
318		if actions == nil {
319			return nil
320		}
321		copied := make([]string, len(actions))
322		copy(copied, actions)
323		return copied
324	}
325	
326	// sameActions 将 nil 与空切片视为等价，其余按顺序逐字比较。
327	func sameActions(a, b []string) bool {
328		if len(a) != len(b) {
329			return false
330		}
331		for i := range a {
332			if a[i] != b[i] {
333				return false
334			}
335		}
336		return true
337	}
338	
339	// ---- 执行 ----
340	
341	// Execute 按编号执行一项提案。调用方通过 now 提供当前时间。
342	// 只有 passed 状态、now 已达到时间锁且动作非空的提案可以首次执行；
343	// 成功后状态变为 executed 并返回凭据。资格不符、动作格式错误、余额不足、
344	// 金额计算溢出都返回明确原因，整项提案不产生部分转账，也不消耗执行机会。
345	// 已完成提案再次执行（即使 now 不同）直接返回首次成功凭据。
346	func (s *Store) Execute(id string, now int64) (*Receipt, error) {
347		commit, err := s.begin()
348		if err != nil {
349			return nil, err
350		}
351		defer commit()
352	
353		state, err := s.loadLocked()
354		if err != nil {
355			return nil, err
356		}
357		proposal, ok := state.Proposals[id]
358		if !ok {
359			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
360		}
361		if proposal.State == "executed" {
362			if rcpt := findReceipt(state.Receipts, id); rcpt != nil {
363				return cloneReceipt(rcpt), nil
364			}
365			return nil, fmt.Errorf("%w: executed proposal %s has no receipt", ErrStateCorrupt, id)
366		}
367		if proposal.State != "passed" {
368			return nil, execReject(fmt.Sprintf("proposal %s is not passed (state=%s)", id, proposal.State))
369		}
370		if now < proposal.TimelockEnd {
371			return nil, execReject(fmt.Sprintf("timelock not reached for %s: now=%d timelock_end=%d", id, now, proposal.TimelockEnd))
372		}
373		if len(proposal.Actions) == 0 {
374			return nil, execReject(fmt.Sprintf("proposal %s has no actions", id))
375		}
376	
377		// 第一阶段：在副本上校验并预演全部动作。任何一步失败都不得落盘。
378		type step struct {
379			account        string
380			amount         int64
381			treasuryBefore int64
382			treasuryAfter  int64
383			accountBefore  int64
384			accountAfter   int64
385		}
386		simTreasury := state.Treasury
387		simBalances := map[string]int64{}
388		for k, v := range state.Balances {
389			simBalances[k] = v
390		}
391		steps := make([]step, 0, len(proposal.Actions))
392		for i, raw := range proposal.Actions {
393			account, amount, perr := ParseTransfer(raw)
394			if perr != nil {
395				// 双 %w：调用方既可按 ErrExecutionRejected 判定执行被拒，
396				// 也可按 ErrInvalidAction 区分“动作格式错误”这一具体原因。
397				return nil, fmt.Errorf("%w: action %d (%q): %w", ErrExecutionRejected, i, raw, perr)
398			}
399			balanceBefore := simBalances[account]
400			balanceAfter, ok := addInt64(balanceBefore, amount)
401			if !ok {
402				return nil, execReject(fmt.Sprintf("recipient balance overflow at action %d: account=%s balance=%d amount=%d", i, account, balanceBefore, amount))
403			}
404			if simTreasury < amount {
405				return nil, execReject(fmt.Sprintf("insufficient treasury balance at action %d: treasury=%d amount=%d", i, simTreasury, amount))
406			}
407			treasuryBefore := simTreasury
408			simTreasury -= amount
409			simBalances[account] = balanceAfter
410			steps = append(steps, step{
411				account:        account,
412				amount:         amount,
413				treasuryBefore: treasuryBefore,
414				treasuryAfter:  simTreasury,
415				accountBefore:  balanceBefore,
416				accountAfter:   balanceAfter,
417			})
418		}
419	
420		// 第二阶段：全部预演成功后构造凭据并一次性原子提交。
421		receipt := &Receipt{
422			ProposalID: id,
423			ExecutedAt: now,
424			Order:      len(state.Receipts),
425			Actions:    make([]ActionReceipt, 0, len(steps)),
426		}
427		for i, st := range steps {
428			receipt.Actions = append(receipt.Actions, ActionReceipt{
429				Index:  i,
430				Action: proposal.Actions[i],
431				Treasury: BalanceUpdate{
432					Account: "treasury",
433					Before:  st.treasuryBefore,
434					After:   st.treasuryAfter,
435				},
436				Recipient: BalanceUpdate{
437					Account: st.account,
438					Before:  st.accountBefore,
439					After:   st.accountAfter,
440				},
441			})
442		}
443		state.Treasury = simTreasury
444		state.Balances = simBalances
445		proposal.State = "executed"
446		state.Receipts = append(state.Receipts, receipt)
447	
448		if err := s.commitLocked(state); err != nil {
449			return nil, err
450		}
451		return cloneReceipt(receipt), nil
452	}
453	
454	func findReceipt(receipts []*Receipt, id string) *Receipt {
455		for _, r := range receipts {
456			if r.ProposalID == id {
457				return r
458			}
459		}
460		return nil
461	}
462	
463	func cloneReceipt(r *Receipt) *Receipt {
464		if r == nil {
465			return nil
466		}
467		copied := *r
468		if r.Actions != nil {
469			copied.Actions = make([]ActionReceipt, len(r.Actions))
470			copy(copied.Actions, r.Actions)
471		}
472		return &copied
473	}
474	
475	// ---- 查询 ----
476	
477	// TreasuryBalance 返回资金库当前余额。
478	func (s *Store) TreasuryBalance() (int64, error) {
479		state, err := s.readState()
480		if err != nil {
481			return 0, err
482		}
483		return state.Treasury, nil
484	}
485	
486	// Balance 返回收款账户余额；从未出现过的账户余额为零。
487	func (s *Store) Balance(account string) (int64, error) {
488		state, err := s.readState()
489		if err != nil {
490			return 0, err
491		}
492		return state.Balances[account], nil
493	}
494	
495	// Balances 返回全部出现过的收款账户余额的副本，按账户名排序。
496	func (s *Store) Balances() (map[string]int64, error) {
497		state, err := s.readState()
498		if err != nil {
499			return nil, err
500		}
501		out := make(map[string]int64, len(state.Balances))
502		for k, v := range state.Balances {
503			out[k] = v
504		}
505		return out, nil
506	}
507	
508	// Proposal 按编号返回提案登记信息；不存在时 ok 为 false。
509	func (s *Store) Proposal(id string) (ProposalRecord, bool, error) {
510		state, err := s.readState()
511		if err != nil {
512			return ProposalRecord{}, false, err
513		}
514		p, ok := state.Proposals[id]
515		if !ok {
516			return ProposalRecord{}, false, nil
517		}
518		return toProposalRecord(p), true, nil
519	}
520	
521	// Proposals 返回全部已登记提案，按编号排序。
522	func (s *Store) Proposals() ([]ProposalRecord, error) {
523		state, err := s.readState()
524		if err != nil {
525			return nil, err
526		}
527		out := make([]ProposalRecord, 0, len(state.Proposals))
528		for _, p := range state.Proposals {
529			out = append(out, toProposalRecord(p))
530		}
531		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
532		return out, nil
533	}
534	
535	func toProposalRecord(p *storedProposal) ProposalRecord {
536		return ProposalRecord{
537			ID:          p.ID,
538			State:       p.State,
539			TimelockEnd: p.TimelockEnd,
540			Actions:     copyActions(p.Actions),
541		}
542	}
543	
544	// Receipt 按编号返回执行凭据；尚未成功执行或不存在时 ok 为 false。
545	func (s *Store) Receipt(id string) (*Receipt, bool, error) {
546		state, err := s.readState()
547		if err != nil {
548			return nil, false, err
549		}
550		r := findReceipt(state.Receipts, id)
551		if r == nil {
552			return nil, false, nil
553		}
554		return cloneReceipt(r), true, nil
555	}
556	
557	// Receipts 按成功提交的先后顺序返回全部执行凭据的副本。
558	func (s *Store) Receipts() ([]*Receipt, error) {
559		state, err := s.readState()
560		if err != nil {
561			return nil, err
562		}
563		out := make([]*Receipt, 0, len(state.Receipts))
564		for _, r := range state.Receipts {
565			out = append(out, cloneReceipt(r))
566		}
567		return out, nil
568	}
569	
570	func (s *Store) readState() (*storedState, error) {
571		commit, err := s.begin()
572		if err != nil {
573			return nil, err
574		}
575		defer commit()
576		return s.loadLocked()
577	}
578	
579	// ---- 持久化 ----
580	
581	// loadLocked 读取、严格解析并重放校验状态文件。调用方必须持锁。
582	func (s *Store) loadLocked() (*storedState, error) {
583		raw, err := os.ReadFile(s.path)
584		if err != nil {
585			return nil, err
586		}
587		if len(bytes.TrimSpace(raw)) == 0 {
588			return nil, fmt.Errorf("%w: %s: file is empty", ErrStateCorrupt, s.path)
589		}
590		if err := rejectDuplicateKeys(raw); err != nil {
591			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
592		}
593		var state storedState
594		dec := json.NewDecoder(bytes.NewReader(raw))
595		dec.DisallowUnknownFields()
596		if err := dec.Decode(&state); err != nil {
597			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
598		}
599		if err := validateState(&state); err != nil {
600			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
601		}
602		return &state, nil
603	}
604	
605	// commitLocked 序列化状态并以“临时文件 + fsync + 原子改名 + 目录 fsync”提交。
606	// 任一步失败都保留上次完整状态。调用方必须持锁。
607	func (s *Store) commitLocked(state *storedState) error {
608		if err := validateState(state); err != nil {
609			return fmt.Errorf("refusing to persist invalid state: %w", err)
610		}
611		payload, err := json.MarshalIndent(state, "", "  ")
612		if err != nil {
613			return err
614		}
615		payload = append(payload, '\n')
616	
617		dir := filepath.Dir(s.path)
618		tmp, err := os.CreateTemp(dir, ".govflow-state-*")
619		if err != nil {
620			return err
621		}
622		tmpName := tmp.Name()
623		cleanup := func() { _ = os.Remove(tmpName) }
624		if _, err := tmp.Write(payload); err != nil {
625			_ = tmp.Close()
626			cleanup()
627			return err
628		}
629		if err := tmp.Sync(); err != nil {
630			_ = tmp.Close()
631			cleanup()
632			return err
633		}
634		if err := tmp.Close(); err != nil {
635			cleanup()
636			return err
637		}
638		if err := os.Chmod(tmpName, 0o600); err != nil {
639			cleanup()
640			return err
641		}
642		if err := os.Rename(tmpName, s.path); err != nil {
643			cleanup()
644			return err
645		}
646		if err := syncDir(dir); err != nil {
647			return err
648		}
649		return nil
650	}
651	
652	func syncDir(dir string) error {
653		d, err := os.Open(dir)
654		if err != nil {
655			return err
656		}
657		defer d.Close()
658		return d.Sync()
659	}
660	
661	// validateState 做结构校验并重放全部凭据，确认余额与凭据完全一致。
662	func validateState(state *storedState) error {
663		if state.Magic != stateMagic {
664			return fmt.Errorf("bad magic %q", state.Magic)
665		}
666		if state.Version != stateVersion {
667			return fmt.Errorf("unsupported state version %d", state.Version)
668		}
669		if state.InitialTreasury < 0 {
670			return errors.New("initial treasury balance is negative")
671		}
672		if state.Treasury < 0 {
673			return errors.New("treasury balance is negative")
674		}
675		if state.Balances == nil {
676			return errors.New("balances table is missing")
677		}
678		if state.Proposals == nil {
679			return errors.New("proposals table is missing")
680		}
681		if state.Receipts == nil {
682			return errors.New("receipts table is missing")
683		}
684		for account, balance := range state.Balances {
685			if account == "" {
686				return errors.New("balance entry with empty account")
687			}
688			if balance < 0 {
689				return fmt.Errorf("balance of %q is negative", account)
690			}
691		}
692		for key, p := range state.Proposals {
693			if p == nil {
694				return fmt.Errorf("proposal %q is empty", key)
695			}
696			if p.ID != key || p.ID == "" {
697				return fmt.Errorf("proposal key %q does not match id %q", key, p.ID)
698			}
699			if p.State != "passed" && p.State != "executed" {
700				return fmt.Errorf("proposal %q has unknown state %q", p.ID, p.State)
701			}
702			for _, action := range p.Actions {
703				// 动作原文登记时不做改写；空串或非法原文留待执行时拒绝。
704				_ = action
705			}
706		}
707	
708		// 重放凭据：从初始资金库余额出发，按成功顺序重放每笔转账，
709		// 校验凭据内的前后余额、最终资金库与各账户余额，并检查状态一致性。
710		simTreasury := state.InitialTreasury
711		simBalances := map[string]int64{}
712		seenReceipts := map[string]int{}
713		for order, rcpt := range state.Receipts {
714			if rcpt == nil {
715				return fmt.Errorf("receipt %d is empty", order)
716			}
717			if rcpt.Order != order {
718				return fmt.Errorf("receipt %q order field is %d, expected %d", rcpt.ProposalID, rcpt.Order, order)
719			}
720			if prev, dup := seenReceipts[rcpt.ProposalID]; dup {
721				return fmt.Errorf("duplicate receipt for %q at positions %d and %d", rcpt.ProposalID, prev, order)
722			}
723			seenReceipts[rcpt.ProposalID] = order
724			proposal, ok := state.Proposals[rcpt.ProposalID]
725			if !ok {
726				return fmt.Errorf("receipt %q references an unregistered proposal", rcpt.ProposalID)
727			}
728			if proposal.State != "executed" {
729				return fmt.Errorf("proposal %q has receipt but state is %q", rcpt.ProposalID, proposal.State)
730			}
731			if len(rcpt.Actions) != len(proposal.Actions) {
732				return fmt.Errorf("receipt %q action count %d does not match proposal %d", rcpt.ProposalID, len(rcpt.Actions), len(proposal.Actions))
733			}
734			for i, ar := range rcpt.Actions {
735				if ar.Index != i {
736					return fmt.Errorf("receipt %q action %d has index %d", rcpt.ProposalID, i, ar.Index)
737				}
738				if ar.Action != proposal.Actions[i] {
739					return fmt.Errorf("receipt %q action %d text does not match registered action", rcpt.ProposalID, i)
740				}
741				account, amount, err := ParseTransfer(ar.Action)
742				if err != nil {
743					return fmt.Errorf("receipt %q action %d is not executable: %v", rcpt.ProposalID, i, err)
744				}
745				if ar.Treasury.Account != "treasury" || ar.Treasury.Before != simTreasury {
746					return fmt.Errorf("receipt %q action %d treasury before-balance mismatch", rcpt.ProposalID, i)
747				}
748				if simTreasury < amount || ar.Treasury.After != simTreasury-amount {
749					return fmt.Errorf("receipt %q action %d treasury after-balance mismatch", rcpt.ProposalID, i)
750				}
751				before := simBalances[account]
752				if ar.Recipient.Account != account || ar.Recipient.Before != before {
753					return fmt.Errorf("receipt %q action %d recipient before-balance mismatch", rcpt.ProposalID, i)
754				}
755				after, ok := addInt64(before, amount)
756				if !ok || ar.Recipient.After != after {
757					return fmt.Errorf("receipt %q action %d recipient after-balance mismatch", rcpt.ProposalID, i)
758				}
759				simTreasury -= amount
760				simBalances[account] = after
761			}
762		}
763		if simTreasury != state.Treasury {
764			return fmt.Errorf("treasury balance %d does not match receipt replay %d", state.Treasury, simTreasury)
765		}
766		if len(simBalances) != len(state.Balances) {
767			return fmt.Errorf("balance table has %d accounts, receipt replay yields %d", len(state.Balances), len(simBalances))
768		}
769		for account, balance := range state.Balances {
770			if simBalances[account] != balance {
771				return fmt.Errorf("balance of %q is %d but receipt replay yields %d", account, balance, simBalances[account])
772			}
773		}
774		// 已执行的提案必须有凭据；passed 提案不得有凭据（上面已部分保证）。
775		for _, p := range state.Proposals {
776			_, hasReceipt := seenReceipts[p.ID]
777			if p.State == "executed" && !hasReceipt {
778				return fmt.Errorf("proposal %q is executed without receipt", p.ID)
779			}
780		}
781		return nil
782	}
783	
784	// scanFrame 是重复键扫描的栈帧。
785	type scanFrame struct {
786		isArray bool
787		seen    map[string]bool
788		atValue bool // 对象帧：下一个待消费 token 是值而非键
789	}
790	
791	func rejectDuplicateKeys(raw []byte) error {
792		dec := json.NewDecoder(bytes.NewReader(raw))
793		var stack []*scanFrame
794		for {
795			tok, err := dec.Token()
796			if err == io.EOF {
797				if len(stack) != 0 {
798					return errors.New("unterminated object or array")
799				}
800				return nil
801			}
802			if err != nil {
803				return err
804			}
805			switch t := tok.(type) {
806			case json.Delim:
807				switch t {
808				case '{':
809					stack = append(stack, &scanFrame{seen: map[string]bool{}})
810					continue
811				case '[':
812					stack = append(stack, &scanFrame{isArray: true})
813					continue
814				case '}', ']':
815					if len(stack) == 0 {
816						return errors.New("unexpected closing delimiter")
817					}
818					stack = stack[:len(stack)-1]
819					// 关闭的容器本身是外层对象的某个“值”，消费完毕后外层等待下一个键。
820					if len(stack) > 0 && !stack[len(stack)-1].isArray {
821						stack[len(stack)-1].atValue = false
822					}
823					continue
824				}
825			default:
826				// 标量 token。
827			}
828			if len(stack) > 0 && !stack[len(stack)-1].isArray {
829				frame := stack[len(stack)-1]
830				if !frame.atValue {
831					key, ok := tok.(string)
832					if !ok {
833						return errors.New("object key must be a string")
834					}
835					if frame.seen[key] {
836						return fmt.Errorf("duplicate key %q", key)
837					}
838					frame.seen[key] = true
839					frame.atValue = true
840				} else {
841					frame.atValue = false
842				}
843			}
844		}
845	}
