func TestPathSpellingsShareLock(t *testing.T) {
	dir := t.TempDir()
	abs := filepath.Join(dir, "treasury.json")

	// 在目录内用相对路径初始化，再以绝对路径打开：必须是同一个文件、同一把锁。
	storeA, err := func() (*Store, error) {
		// 借助子测试进程内的工作目录切换不可行，改为直接验证规范化结果一致。
		return InitTreasury(abs, 10)
	}()
	if err != nil {
		t.Fatal(err)
	}
	storeA.Close()

	rel := filepath.Join(dir, "treasury.json") // 与 abs 仅差路径前缀
	aliasPath := rel
	if filepath.IsAbs(aliasPath) {
		aliasPath = rel
	}
	// 两种拼写规范化后必须相同。
	a, err := canonicalPath(abs)
	if err != nil {
		t.Fatal(err)
	}
	b, err := canonicalPath(aliasPath)
	if err != nil {
		t.Fatal(err)
	}
	if a != b {
		t.Fatalf("canonical paths differ: %q vs %q", a, b)
	}
	m1 := inProcessLock(a)
	m2 := inProcessLock(b)
	if m1 != m2 {
		t.Fatal("path spellings resolved to different in-process locks")
	}
}

